<?php
require_once 'config.php'; require_once 'includes/auth_check.php'; require_once 'includes/security.php'; require_once 'includes/pdf_helper.php';
if(($_SESSION['user_role']??'')!=='admin'){http_response_code(403);exit('Administrator access required.');}
$format=$_GET['format']??'csv'; $status=$_GET['status']??''; $priority=$_GET['priority']??''; $where=[];$params=[];$types='';if($status!==''){$where[]='c.status=?';$types.='s';$params[]=$status;}if($priority!==''){$where[]='c.priority=?';$types.='s';$params[]=$priority;}$sql='SELECT c.reference_no,c.subject,c.category,c.priority,c.status,c.created_at,c.sla_due_at,c.feedback_rating,c.is_anonymous,d.name department_name,u.full_name owner_name FROM complaints c LEFT JOIN departments d ON d.id=c.department_id LEFT JOIN users u ON u.id=c.user_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY c.created_at DESC';$stmt=$conn->prepare($sql);if($params)$stmt->bind_param($types,...$params);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();audit_log($conn,'export','complaints',null,'Administrator exported '.count($rows).' complaint records as '.$format);
if($format==='pdf'){ $lines=['Generated: '.date('Y-m-d H:i:s'),'Filters: '.($status?:'All statuses').' / '.($priority?:'All priorities'),'','Reference | Subject | Priority | Status | SLA'];foreach($rows as $r){$lines[]=substr($r['reference_no'].' | '.$r['subject'].' | '.$r['priority'].' | '.$r['status'].' | '.($r['sla_due_at']??'n/a'),0,110);}output_text_pdf('complaint-report-'.date('Ymd-His').'.pdf','Grievance Portal - Complaint Report',$lines); }
header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="complaint-report-'.date('Ymd-His').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Reference','Subject','Category','Priority','Status','Created at','SLA due','Feedback rating','Anonymous','Department','Complainant']);foreach($rows as $r)fputcsv($out,[$r['reference_no'],$r['subject'],$r['category'],$r['priority'],$r['status'],$r['created_at'],$r['sla_due_at'],$r['feedback_rating'],$r['is_anonymous']?'Yes':'No',$r['department_name'],$r['is_anonymous']?'Hidden':$r['owner_name']]);fclose($out);exit;
